import { createContext, useCallback, useContext, useEffect, useRef, useState, type ReactNode } from 'react'
import { getJson } from '../api/client'
import type { MeResponse, Tenant } from '../api/types'

type ActorState = { actorEmail: string; tenant: Tenant | null; generation: number; loading: boolean; error: string | null; writeInFlight: boolean; beginWrite: (key: string) => boolean; endWrite: (key: string) => void; switchActor: (email: string) => void; retry: () => void }
const ActorContext = createContext<ActorState | null>(null)

export function ActorProvider({ children }: { children: ReactNode }) {
  const [actorEmail, setActorEmail] = useState('alice@east.test')
  const [tenant, setTenant] = useState<Tenant | null>(null)
  const [generation, setGeneration] = useState(0)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [writeInFlight, setWriteInFlight] = useState(false)
  const activeWriteKeys = useRef(new Set<string>())
  const requestId = useRef(0)

  useEffect(() => {
    const id = ++requestId.current
    const controller = new AbortController()
    setLoading(true); setError(null); setTenant(null)
    getJson<MeResponse>('/api/me', actorEmail, controller.signal).then(data => {
      if (id === requestId.current) { setTenant(data.tenant); setLoading(false) }
    }).catch(cause => {
      if (id !== requestId.current || controller.signal.aborted) return
      setError(cause instanceof Error ? cause.message : '无法确认管理员身份'); setLoading(false)
    })
    return () => { controller.abort(); requestId.current++ }
  }, [actorEmail, generation])

  const switchActor = useCallback((email: string) => {
    if (!writeInFlight && email !== actorEmail) { setTenant(null); setLoading(true); setActorEmail(email); setGeneration(value => value + 1) }
  }, [actorEmail, writeInFlight])
  const retry = useCallback(() => setGeneration(value => value + 1), [])
  const beginWrite = useCallback((key: string) => {
    if (activeWriteKeys.current.has(key)) return false
    activeWriteKeys.current.add(key)
    setWriteInFlight(true)
    return true
  }, [])
  const endWrite = useCallback((key: string) => {
    activeWriteKeys.current.delete(key)
    setWriteInFlight(activeWriteKeys.current.size > 0)
  }, [])
  return <ActorContext.Provider value={{ actorEmail, tenant, generation, loading, error, writeInFlight, beginWrite, endWrite, switchActor, retry }}>{children}</ActorContext.Provider>
}

export function useActor(): ActorState {
  const context = useContext(ActorContext)
  if (!context) throw new Error('ActorProvider is missing')
  return context
}
export type PendingWrite = { actorEmail: string; method: 'POST'; path: string; body: object; key: string; createdAt: number }
const storageKey = 'ocean-pending-write'
export function createPendingWrite(actorEmail: string, path: string, body: object): PendingWrite { return { actorEmail, method: 'POST', path, body, key: crypto.randomUUID(), createdAt: Date.now() } }
function readPending(): PendingWrite[] {
  const raw = sessionStorage.getItem(storageKey)
  if (!raw) return []
  try {
    const values = JSON.parse(raw) as unknown
    return Array.isArray(values) ? values.filter((value): value is PendingWrite => value?.method === 'POST' && typeof value.key === 'string' && typeof value.path === 'string') : []
  } catch { return [] }
}
export function loadPendingWrite(actorEmail?: string, path?: string): PendingWrite | null {
  return readPending().filter(value => (!actorEmail || value.actorEmail === actorEmail) && (!path || value.path === path)).at(-1) ?? null
}
export function savePendingWrite(write: PendingWrite): void {
  const values = readPending().filter(value => value.key !== write.key)
  values.push(write)
  sessionStorage.setItem(storageKey, JSON.stringify(values))
}
export function clearPendingWrite(write?: PendingWrite): void {
  if (!write) { sessionStorage.removeItem(storageKey); return }
  sessionStorage.setItem(storageKey, JSON.stringify(readPending().filter(value => value.key !== write.key)))
}
import type { PendingWrite } from './pendingWrite'
import { clearPendingWrite, savePendingWrite } from './pendingWrite'
import { postJson } from '../api/client'

export async function submitWrite<T>(write: PendingWrite): Promise<T> {
  savePendingWrite(write)
  const result = await postJson<T>(write.path, write.actorEmail, write.key, write.body)
  clearPendingWrite(write)
  return result
}
export class ApiError extends Error {
  constructor(public status: number, message: string) { super(message); this.name = 'ApiError' }
}

async function parseJson<T>(response: Response): Promise<T> {
  let body: unknown
  try { body = await response.json() } catch { body = null }
  if (!response.ok) {
    const message = typeof body === 'object' && body !== null && 'message' in body && typeof body.message === 'string' ? body.message : `请求失败（${response.status}）`
    throw new ApiError(response.status, message)
  }
  return body as T
}

export async function getJson<T>(path: string, actorEmail: string, signal?: AbortSignal): Promise<T> {
  const response = await fetch(path, { headers: { 'X-Actor-Email': actorEmail }, cache: 'no-store', signal })
  return parseJson<T>(response)
}

export async function postJson<T>(path: string, actorEmail: string, key: string, body: object = {}): Promise<T> {
  const response = await fetch(path, { method: 'POST', headers: { 'X-Actor-Email': actorEmail, 'Idempotency-Key': key, 'Content-Type': 'application/json' }, body: JSON.stringify(body) })
  return parseJson<T>(response)
}
