    70	    {selectedId !== null && <CertificateDrawer id={selectedId} actorEmail={actorEmail} onClose={() => setSelectedId(null)} onChanged={() => setRevision(value => value + 1)} />}
    71	  </section>
    72	}
97:- [ ] 实现参数白名单、姓名/序列号不区分大小写子串搜索、列表总数与行的同一读事务、租户范围详情和 `Cache-Control: no-store`。
